// Frontend/src/pages/FeedPage.tsx - Twitter Style
import React, { useState, useEffect } from 'react';
import { postsAPI, likesAPI, commentsAPI } from '../services/api';
import { useAuth } from '../contexts/AuthContext';

interface Post {
  id: string;
  title: string;
  description: string;
  location: string;
  imageUrl: string;
  userId: string;
  user: {
    id: string;
    name: string;
    avatar: string;
  };
  _count: {
    likes: number;
    comments: number;
  };
  createdAt: string;
  comments?: Comment[];
  isLiked?: boolean;
}

interface Comment {
  id: string;
  text: string;
  user: {
    id: string;
    name: string;
    avatar: string;
  };
  createdAt: string;
}

const FeedPage: React.FC = () => {
  const { userId, userName, userAvatar } = useAuth();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredPosts, setFilteredPosts] = useState<Post[]>([]);

  useEffect(() => {
  if (!searchQuery.trim()) {
    setFilteredPosts(posts);
  } else {
    const filtered = posts.filter((post) =>
      post.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      post.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      post.location.toLowerCase().includes(searchQuery.toLowerCase())
    );
    setFilteredPosts(filtered);
  }
}, [searchQuery, posts]);


  // Modal state
  const [showModal, setShowModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [commentText, setCommentText] = useState('');

  // Form state
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    location: '',
    imageUrl: '',
    lat: null as number | null,
    lng: null as number | null,
  });

  const [showMap, setShowMap] = useState(false);

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    try {
      setLoading(true);
      const data = await postsAPI.getAllPosts();
      
      // Check which posts current user has liked
      if (userId) {
        const postsWithLikeStatus = await Promise.all(
          data.map(async (post: Post) => {
            try {
              const likeStatus = await likesAPI.checkLike(userId, post.id);
              return { ...post, isLiked: likeStatus.liked };
            } catch {
              return { ...post, isLiked: false };
            }
          })
        );
        setPosts(postsWithLikeStatus);
      } else {
        setPosts(data);
      }
      
      setError('');
    } catch (err: any) {
      setError(err.message || 'Failed to load posts');
      console.error('Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePost = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title || !formData.description || !formData.location) {
      setError('Please fill all fields');
      return;
    }

    if (!userId) {
      setError('Please login first');
      return;
    }

    try {
      const newPost = await postsAPI.createPost({
        ...formData,
        userId,
      });

      setPosts([newPost, ...posts]);
      setFormData({ title: '', description: '', location: '', imageUrl: '', lat: null, lng: null });
      setShowModal(false);
      setShowMap(false);
      setError('');
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleLikePost = async (postId: string) => {
    if (!userId) {
      setError('Please login to like');
      return;
    }

    try {
      const result = await likesAPI.toggleLike(userId, postId);
      setPosts(
        posts.map((p) =>
          p.id === postId
            ? { 
                ...p, 
                _count: { ...p._count, likes: result.likeCount },
                isLiked: result.liked 
              }
            : p
        )
      );
    } catch (err: any) {
      console.error('Like error:', err);
    }
  };

  const handleOpenDetail = async (post: Post) => {
    try {
      const fullPost = await postsAPI.getPostById(post.id);
      setSelectedPost(fullPost);
      setShowDetailModal(true);
    } catch (err) {
      console.error('Error loading post:', err);
    }
  };

  const handleAddComment = async () => {
    if (!commentText.trim() || !userId || !selectedPost) return;

    try {
      const newComment = await commentsAPI.createComment({
        text: commentText,
        userId,
        postId: selectedPost.id,
      });

      setSelectedPost({
        ...selectedPost,
        comments: [newComment, ...(selectedPost.comments || [])],
        _count: { ...selectedPost._count, comments: selectedPost._count.comments + 1 },
      });

      // Update posts list
      setPosts(
        posts.map((p) =>
          p.id === selectedPost.id
            ? { ...p, _count: { ...p._count, comments: p._count.comments + 1 } }
            : p
        )
      );

      setCommentText('');
    } catch (err: any) {
      console.error('Comment error:', err);
    }
  };

  const handleDeletePost = async (postId: string) => {
    if (!window.confirm('Delete this post?')) return;

    try {
      await postsAPI.deletePost(postId);
      setPosts(posts.filter((p) => p.id !== postId));
      setShowDetailModal(false);
    } catch (err: any) {
      setError(err.message);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600"></div>
          <p className="mt-4 text-gray-600">Loading feed...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="max-w-2xl mx-auto">
        {/* Error */}
        {error && (
          <div className="sticky top-16 z-40 mx-4 mt-4 p-3 bg-red-50 border border-red-200 text-red-600 rounded-lg text-sm">
            {error}
          </div>
        )}

        {/* Create Post Button (Twitter-style) */}
        <div className="bg-white border-b border-gray-200 sticky top-16 z-30">
          <div className="p-4">
            <button
              onClick={() => setShowModal(true)}
              className="flex items-center gap-3 w-full p-3 bg-gray-50 hover:bg-gray-100 rounded-full transition-colors text-left"
            >
              <img
                src={userAvatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(userName || 'User')}&background=ea580c&color=fff`}
                alt="Avatar"
                className="w-10 h-10 rounded-full"
              />
              <span className="text-gray-500">Share your hidden gem...</span>
            </button>
          </div>

          {/* Search Bar */}
          <div className="px-4 pb-4">
            <div className="relative">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search restaurants, locations..."
                className="w-full py-2 px-4 pl-10 bg-gray-100 rounded-full focus:outline-none focus:ring-2 focus:ring-orange-500"
              />
              <span className="absolute left-3 top-2.5 text-gray-400">🔍</span>
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-2.5 text-gray-400 hover:text-gray-600"
                >
                  ×
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Posts Feed */}
        <div className="divide-y divide-gray-200">
          {filteredPosts.length === 0 && searchQuery ? (
            <div className="bg-white p-12 text-center">
              <p className="text-gray-600 text-lg mb-2">No results found</p>
              <p className="text-gray-500 text-sm">Try different keywords</p>
            </div>
          ) : filteredPosts.length === 0 ? (
            <div className="bg-white p-12 text-center">
              <p className="text-gray-600 text-lg mb-4">No posts yet!</p>
              <button
                onClick={() => setShowModal(true)}
                className="bg-orange-600 text-white px-6 py-2 rounded-full hover:bg-orange-700"
              >
                Create First Post
              </button>
            </div>
          ) : (
            filteredPosts.map((post) => (
              <div key={post.id} className="bg-white hover:bg-gray-50 transition-colors">
                <div className="p-4">
                  {/* User Header */}
                  <div className="flex items-start gap-3 mb-3">
                    <img
                      src={post.user.avatar || 'https://via.placeholder.com/40'}
                      alt={post.user.name}
                      className="w-10 h-10 rounded-full"
                    />
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-gray-900">{post.user.name}</span>
                        <span className="text-gray-500 text-sm">
                          · {new Date(post.createdAt).toLocaleDateString()}
                        </span>
                      </div>
                      <div className="text-orange-600 text-sm flex items-center gap-1 mt-1">
                        <span>📍</span>
                        <span>{post.location}</span>
                      </div>
                    </div>

                    {/* Delete (if own post) */}
                    {post.userId === userId && (
                      <button
                        onClick={() => handleDeletePost(post.id)}
                        className="text-gray-400 hover:text-red-500 text-sm"
                      >
                        ×
                      </button>
                    )}
                  </div>

                  {/* Content */}
                  <div className="ml-13">
                    <h3 className="font-bold text-lg text-gray-900 mb-1">{post.title}</h3>
                    <p className="text-gray-700 mb-3 whitespace-pre-wrap">{post.description}</p>

                    {/* Image */}
                    {post.imageUrl && (
                      <img
                        src={post.imageUrl}
                        alt={post.title}
                        className="w-full rounded-2xl mb-3 max-h-96 object-cover cursor-pointer"
                        onClick={() => handleOpenDetail(post)}
                      />
                    )}

                    {/* Actions */}
                    <div className="flex items-center gap-6 text-gray-500 pt-2">
                      <button
                        onClick={() => handleOpenDetail(post)}
                        className="flex items-center gap-2 hover:text-blue-500 transition-colors group"
                      >
                        <div className="p-2 rounded-full group-hover:bg-blue-50">
                          💬
                        </div>
                        <span className="text-sm">{post._count.comments}</span>
                      </button>

                      <button
                        onClick={() => handleLikePost(post.id)}
                        className={`flex items-center gap-2 transition-colors group ${
                          post.isLiked ? 'text-red-500' : 'hover:text-red-500'
                        }`}
                      >
                        <div className="p-2 rounded-full group-hover:bg-red-50">
                          {post.isLiked ? '❤️' : '🤍'}
                        </div>
                        <span className="text-sm">{post._count.likes}</span>
                      </button>

                      <button className="flex items-center gap-2 hover:text-green-500 transition-colors group">
                        <div className="p-2 rounded-full group-hover:bg-green-50">
                          🔗
                        </div>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Create Post Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-start justify-center pt-20">
          <div className="bg-white rounded-2xl w-full max-w-xl mx-4 max-h-[80vh] overflow-y-auto">
            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-gray-200">
              <button
                onClick={() => setShowModal(false)}
                className="text-gray-500 hover:text-gray-700 text-xl"
              >
                ×
              </button>
              <h2 className="font-bold text-lg">Create Post</h2>
              <button
                onClick={handleCreatePost}
                disabled={!formData.title || !formData.description || !formData.location}
                className="bg-orange-600 text-white px-4 py-1.5 rounded-full hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
              >
                Post
              </button>
            </div>

            {/* Form */}
            <form onSubmit={handleCreatePost} className="p-4">
              <div className="flex gap-3">
                <img
                  src={userAvatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(userName || 'User')}&background=ea580c&color=fff`}
                  alt="Avatar"
                  className="w-10 h-10 rounded-full flex-shrink-0"
                />

                <div className="flex-1 space-y-4">
                  <input
                    type="text"
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    placeholder="Restaurant name (e.g., Nasi Goreng Pak Budi)"
                    className="w-full text-xl font-semibold focus:outline-none placeholder-gray-400"
                  />

                  <textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    placeholder="What makes this place special?"
                    rows={4}
                    className="w-full resize-none focus:outline-none placeholder-gray-400"
                  />

                  <div className="flex items-center gap-2 text-orange-600">
                    <span>📍</span>
                    <input
                      type="text"
                      value={formData.location}
                      onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                      placeholder="Location (e.g., Jl. Sudirman No. 123)"
                      className="flex-1 focus:outline-none placeholder-gray-400"
                    />
                  </div>

                  <input
                    type="url"
                    value={formData.imageUrl}
                    onChange={(e) => setFormData({ ...formData, imageUrl: e.target.value })}
                    placeholder="Image URL (optional)"
                    className="w-full text-sm focus:outline-none placeholder-gray-400 text-blue-500"
                  />
                </div>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Post Detail Modal (with Comments) */}
      {showDetailModal && selectedPost && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            {/* Header */}
            <div className="sticky top-0 bg-white flex items-center gap-4 p-4 border-b border-gray-200">
              <button
                onClick={() => setShowDetailModal(false)}
                className="text-gray-500 hover:text-gray-700 text-xl"
              >
                ←
              </button>
              <h2 className="font-bold text-lg">Post</h2>
            </div>

            {/* Post Content */}
            <div className="p-4">
              {/* User */}
              <div className="flex items-start gap-3 mb-4">
                <img
                  src={selectedPost.user.avatar}
                  alt={selectedPost.user.name}
                  className="w-12 h-12 rounded-full"
                />
                <div>
                  <div className="font-bold">{selectedPost.user.name}</div>
                  <div className="text-gray-500 text-sm">
                    {new Date(selectedPost.createdAt).toLocaleString()}
                  </div>
                </div>
              </div>

              {/* Content */}
              <h3 className="text-2xl font-bold mb-2">{selectedPost.title}</h3>
              <p className="text-lg mb-3 whitespace-pre-wrap">{selectedPost.description}</p>
              <div className="text-orange-600 mb-4 flex items-center gap-2">
                <span>📍</span>
                <span>{selectedPost.location}</span>
              </div>

              {selectedPost.imageUrl && (
                <img
                  src={selectedPost.imageUrl}
                  alt={selectedPost.title}
                  className="w-full rounded-2xl mb-4"
                />
              )}

              {/* Stats */}
              <div className="flex gap-4 text-sm text-gray-500 pb-3 border-b border-gray-200">
                <span><strong>{selectedPost._count.likes}</strong> likes</span>
                <span><strong>{selectedPost._count.comments}</strong> comments</span>
              </div>

              {/* Actions */}
              <div className="flex items-center justify-around py-2 border-b border-gray-200">
                <button
                  onClick={() => handleLikePost(selectedPost.id)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full hover:bg-red-50 transition-colors ${
                    selectedPost.isLiked ? 'text-red-500' : 'text-gray-500'
                  }`}
                >
                  {selectedPost.isLiked ? '❤️' : '🤍'}
                  <span>Like</span>
                </button>
                <button className="flex items-center gap-2 px-4 py-2 rounded-full hover:bg-blue-50 text-gray-500 transition-colors">
                  💬 <span>Comment</span>
                </button>
              </div>

              {/* Add Comment */}
              <div className="flex gap-3 py-4 border-b border-gray-200">
                <img
                  src={userAvatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(userName || 'User')}&background=ea580c&color=fff`}
                  alt="Avatar"
                  className="w-10 h-10 rounded-full"
                />
                <div className="flex-1">
                  <textarea
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value)}
                    placeholder="Write a comment..."
                    rows={2}
                    className="w-full resize-none focus:outline-none border border-gray-200 rounded-lg p-2"
                  />
                  <div className="flex justify-end mt-2">
                    <button
                      onClick={handleAddComment}
                      disabled={!commentText.trim()}
                      className="bg-orange-600 text-white px-4 py-1.5 rounded-full hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-medium"
                    >
                      Comment
                    </button>
                  </div>
                </div>
              </div>

              {/* Comments List */}
              <div className="space-y-4 pt-4">
                {selectedPost.comments && selectedPost.comments.length > 0 ? (
                  selectedPost.comments.map((comment) => (
                    <div key={comment.id} className="flex gap-3">
                      <img
                        src={comment.user.avatar || 'https://via.placeholder.com/40'}
                        alt={comment.user.name}
                        className="w-10 h-10 rounded-full"
                      />
                      <div className="flex-1">
                        <div className="bg-gray-100 rounded-2xl px-4 py-2">
                          <div className="font-semibold text-sm">{comment.user.name}</div>
                          <p className="text-gray-800">{comment.text}</p>
                        </div>
                        <div className="text-xs text-gray-500 mt-1 ml-4">
                          {new Date(comment.createdAt).toLocaleString()}
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="text-center text-gray-500 py-8">
                    No comments yet. Be the first to comment!
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FeedPage;
